import sys
from datetime import datetime, timezone

def parse_iso8601(instant_str):
    """Parse an offset-aware ISO8601 string to a datetime with timezone."""
    if instant_str is None:
        return None
    # Handle 'Z' suffix by replacing with '+00:00'
    if instant_str.endswith('Z'):
        instant_str = instant_str[:-1] + '+00:00'
    # Parse with timezone info
    try:
        dt = datetime.fromisoformat(instant_str)
        return dt
    except ValueError:
        # Naive datetime (no timezone) - skip it
        return None

def format_utc(dt):
    """Format datetime as YYYY-MM-DDTHH:MM:SSZ"""
    return dt.astimezone(timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')

def main():
    data = json.load(open(sys.argv[1]))
    as_of = parse_iso8601(data['as_of'])
    if as_of is None:
        print(json.dumps([]))
        return

    reminders = data.get('reminders', [])
    result = []

    for r in reminders:
        # Skip completed reminders
        if r.get('completed', False):
            continue

        due_str = r.get('due')
        # Skip null/missing due values
        if due_str is None:
            continue

        due_dt = parse_iso8601(due_str)
        # Skip naive datetime (no timezone info)
        if due_dt is None:
            continue

        # Check if due AT OR BEFORE as_of
        if due_dt <= as_of:
            result.append({
                'id': r['id'],
                'title': r['title'],
                'due_utc': format_utc(due_dt)
            })

    # Sort by actual due instant (using the parsed datetime) then by id
    # We need to re-parse for sorting since we lost the original datetime
    def sort_key(item):
        dt = parse_iso8601(item['due_utc'].replace('Z', '+00:00'))
        return (dt, item['id'])

    # Actually, we should sort based on the original due datetime.
    # Let's restructure to keep the datetime for sorting.

    # Re-process to keep datetime for sorting
    filtered = []
    for r in reminders:
        if r.get('completed', False):
            continue
        due_str = r.get('due')
        if due_str is None:
            continue
        due_dt = parse_iso8601(due_str)
        if due_dt is None:
            continue
        if due_dt <= as_of:
            filtered.append((due_dt, r['id'], r['title']))

    # Sort by due instant then id
    filtered.sort(key=lambda x: (x[0], x[1]))

    # Build result
    result = [
        {'id': id_, 'title': title, 'due_utc': format_utc(dt)}
        for dt, id_, title in filtered
    ]

    print(json.dumps(result))

if __name__ == '__main__':
    main()"}

